from pathlib import Path
import base64, hashlib, subprocess, sys, zlib

root = Path(sys.argv[1]).resolve()
payload = ''
patch = zlib.decompress(base64.b64decode(payload))
expected = '0789877ef55fa8ae49eca22f850b58f14b02509ca5e1512550ea15efa8a34517'
actual = hashlib.sha256(patch).hexdigest()
if actual != expected:
    raise RuntimeError(f"alpha51e Shop UI patch checksum mismatch: {actual} != {expected}")
subprocess.run(["git", "-C", str(root), "apply", "--whitespace=nowarn", "-"], input=patch, check=True)
print("PKVault V8 alpha51e Shop visual parity pass applied")
